SET plan_cache_mode=force_generic_plan; SET jit=off; SET max_parallel_workers_per_gather=0; PREPARE old(bigint) AS SELECT count(*) FROM (SELECT 1 FROM articles a WHERE a.author_id IN (SELECT fo.followee_id FROM follows fo WHERE fo.follower_id = $1) LIMIT 1000) s; PREPARE candidate(bigint) AS SELECT count(*) FROM (SELECT 1 FROM follows fo CROSS JOIN LATERAL (SELECT 1 FROM articles a WHERE a.author_id = fo.followee_id LIMIT 1000) x WHERE fo.follower_id = $1 LIMIT 1000) s;EXPLAIN (ANALYZE,BUFFERS,FORMAT JSON) EXECUTE old(1);EXPLAIN (ANALYZE,BUFFERS,FORMAT JSON) EXECUTE candidate(1);EXPLAIN (ANALYZE,BUFFERS,FORMAT JSON) EXECUTE old(123);EXPLAIN (ANALYZE,BUFFERS,FORMAT JSON) EXECUTE candidate(123);EXPLAIN (ANALYZE,BUFFERS,FORMAT JSON) EXECUTE old(20000);EXPLAIN (ANALYZE,BUFFERS,FORMAT JSON) EXECUTE candidate(20000);EXPLAIN (ANALYZE,BUFFERS,FORMAT JSON) EXECUTE old(50000);EXPLAIN (ANALYZE,BUFFERS,FORMAT JSON) EXECUTE candidate(50000);EXPLAIN (ANALYZE,BUFFERS,FORMAT JSON) EXECUTE old(99999);EXPLAIN (ANALYZE,BUFFERS,FORMAT JSON) EXECUTE candidate(99999);
